class Solution:
    def connectTwoGroups(self, cost: List[List[int]]) -> int:
        m, n = len(cost), len(cost[0])
        full = (1 << n) - 1

        @lru_cache(None)
        def dfs(i, mask):
            if i == m:
                return 0 if mask == full else float('inf')
            best = float('inf')
            for j in range(n):
                best = min(best, cost[i][j] + dfs(i + 1, mask | 1 << j))
            avail = full & ~mask
            s = avail
            while s:
                if bin(s).count('1') >= 2:
                    add = sum(cost[i][j] for j in range(n) if s >> j & 1)
                    best = min(best, add + dfs(i + 1, mask | s))
                s = (s - 1) & avail
            return best

        return dfs(0, 0)

