class Solution {
public:
    int connectTwoGroups(vector<vector<int>>& cost) {
        int m = cost.size(), n = cost[0].size(), full = (1 << n) - 1;
        vector<vector<int>> memo(m, vector<int>(1 << n, -1));
        function<int(int,int)> dfs = [&](int i, int mask) -> int {
            if (i == m) return mask == full ? 0 : INT_MAX / 2;
            int& res = memo[i][mask];
            if (res != -1) return res;
            res = INT_MAX / 2;
            for (int j = 0; j < n; ++j)
                res = min(res, cost[i][j] + dfs(i + 1, mask | 1 << j));
            int avail = full & ~mask;
            for (int s = avail; s; s = (s - 1) & avail) {
                if (__builtin_popcount((unsigned)s) < 2) continue;
                int add = 0;
                for (int j = 0; j < n; ++j)
                    if (s >> j & 1) add += cost[i][j];
                res = min(res, add + dfs(i + 1, mask | s));
            }
            return res;
        };
        return dfs(0, 0);
    }
};

