class Solution {
    private List<List<Integer>> cost;
    private int[][] memo;
    private int n, full;

    public int connectTwoGroups(List<List<Integer>> cost) {
        this.cost = cost;
        int m = cost.size();
        n = cost.get(0).size();
        full = (1 << n) - 1;
        memo = new int[m][1 << n];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dfs(0, 0);
    }

    private int dfs(int i, int mask) {
        if (i == cost.size()) return mask == full ? 0 : Integer.MAX_VALUE / 2;
        if (memo[i][mask] != -1) return memo[i][mask];
        int res = Integer.MAX_VALUE / 2;
        for (int j = 0; j < n; j++)
            res = Math.min(res, cost.get(i).get(j) + dfs(i + 1, mask | (1 << j)));
        int avail = full & ~mask;
        for (int s = avail; s > 0; s = (s - 1) & avail) {
            if (Integer.bitCount(s) < 2) continue;
            int add = 0;
            for (int j = 0; j < n; j++)
                if ((s >> j & 1) == 1) add += cost.get(i).get(j);
            res = Math.min(res, add + dfs(i + 1, mask | s));
        }
        return memo[i][mask] = res;
    }
}

