var connectTwoGroups = function(cost) {
    const m = cost.length, n = cost[0].length, full = (1 << n) - 1;
    const memo = Array.from({length: m}, () => Array(1 << n).fill(-1));
    const dfs = (i, mask) => {
        if (i === m) return mask === full ? 0 : Infinity;
        if (memo[i][mask] !== -1) return memo[i][mask];
        let best = Infinity;
        for (let j = 0; j < n; j++)
            best = Math.min(best, cost[i][j] + dfs(i + 1, mask | (1 << j)));
        const avail = full & ~mask;
        for (let s = avail; s > 0; s = (s - 1) & avail) {
            let bits = 0, add = 0;
            for (let j = 0; j < n; j++) if ((s >> j) & 1) { bits++; add += cost[i][j]; }
            if (bits < 2) continue;
            best = Math.min(best, add + dfs(i + 1, mask | s));
        }
        return (memo[i][mask] = best);
    };
    return dfs(0, 0);
};

