class Solution {
public:
    int connectTwoGroups(vector<vector<int>>& cost) {
        int m = cost.size(), n = cost[0].size(), full = 1 << n;
        vector<int> minCol(n, INT_MAX);
        for (int j = 0; j < n; ++j)
            for (int i = 0; i < m; ++i)
                minCol[j] = min(minCol[j], cost[i][j]);
        const int INF = INT_MAX / 2;
        vector<int> dp(full, INF);
        dp[0] = 0;
        for (int i = 0; i < m; ++i) {
            vector<int> ndp(full, INF);
            for (int mask = 0; mask < full; ++mask) {
                if (dp[mask] >= INF) continue;
                for (int j = 0; j < n; ++j)
                    ndp[mask | (1 << j)] = min(ndp[mask | (1 << j)], dp[mask] + cost[i][j]);
            }
            dp.swap(ndp);
        }
        int ans = INF;
        for (int mask = 0; mask < full; ++mask) {
            if (dp[mask] >= INF) continue;
            int extra = 0;
            for (int j = 0; j < n; ++j)
                if (!(mask >> j & 1)) extra += minCol[j];
            ans = min(ans, dp[mask] + extra);
        }
        return ans;
    }
};

