var connectTwoGroups = function(cost) {
    const m = cost.length, n = cost[0].length, full = 1 << n;
    const minCol = Array(n).fill(Infinity);
    for (let j = 0; j < n; j++)
        for (let i = 0; i < m; i++) minCol[j] = Math.min(minCol[j], cost[i][j]);
    const INF = Infinity;
    let dp = Array(full).fill(INF);
    dp[0] = 0;
    for (let i = 0; i < m; i++) {
        const ndp = Array(full).fill(INF);
        for (let mask = 0; mask < full; mask++) {
            if (dp[mask] === INF) continue;
            for (let j = 0; j < n; j++) {
                const nm = mask | (1 << j);
                if (dp[mask] + cost[i][j] < ndp[nm]) ndp[nm] = dp[mask] + cost[i][j];
            }
        }
        dp = ndp;
    }
    let ans = INF;
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] === INF) continue;
        let extra = 0;
        for (let j = 0; j < n; j++) if (!((mask >> j) & 1)) extra += minCol[j];
        ans = Math.min(ans, dp[mask] + extra);
    }
    return ans;
};
